export type SecurityScope = "azure" | "m365" | "combined";
export type GuideCheck = { action: string; expected: string; evidence: string };
export type GuideStep = { title: string; configure: string; location: string; decision: string; avoid: string; outcome: string };
export type Playbook = {
  id: string; domainId: string; domain: string; subdomain: string; priority: "Baseline" | "Recommended" | "Advanced";
  type: "Preventive" | "Detective" | "Responsive" | "Governance" | "Recovery";
  phase: string; sequence: number; scope: SecurityScope | "all"; prerequisiteControlIds: string[]; keywords: string[]; workloads: string[]; products: string[]; objective: string; applicability: string;
  prerequisites: string[]; decisions: string[]; steps: GuideStep[]; validation: GuideCheck[];
  failures: string[]; operations: string[]; licensing: string; frameworks: string[]; references: { label: string; url: string }[];
};

