const domainScope: Record<string, SecurityScope | "all"> = {
  governance:"azure", identity:"all", privileged:"all", network:"azure", workload:"azure", containers:"azure", data:"all", secrets:"azure", posture:"azure", cnapp:"azure", vulnerability:"all", logging:"all", siem:"all", response:"all", m365identity:"m365", email:"m365", endpoint:"m365", device:"m365", saas:"m365", purview:"all", ai:"all", copilot:"all", recovery:"all", devsecops:"all", compliance:"all", multicloud:"azure",
};
const domainSequence: Record<string, number> = Object.fromEntries(["governance","identity","privileged","network","workload","containers","data","secrets","posture","cnapp","vulnerability","logging","siem","response","m365identity","email","endpoint","device","saas","purview","ai","copilot","recovery","devsecops","compliance","multicloud"].map((id,index)=>[id,(index+1)*10]));

const makeGuide = (data: Omit<Playbook, "steps" | "validation" | "failures" | "operations" | "scope" | "sequence" | "prerequisiteControlIds" | "keywords"> & {
  steps: [string, string, string, string]; validation: [string, string];
}): Playbook => ({
  ...data,
  scope: domainScope[data.domainId] ?? "all",
  sequence: domainSequence[data.domainId] ?? 999,
  prerequisiteControlIds: guideDependencies[data.id] ?? [],
  keywords: [data.id, data.domain, data.subdomain, ...data.products, ...data.workloads],
  steps: data.steps.map((title, index) => ({
    title,
    configure: [
      `Establish the current state for ${data.domain.toLowerCase()}; record the owner, scope and systems in the change record before changing configuration.`,
      `Configure the selected ${data.products.join(" / ")} capability at the smallest supported scope. Use a pilot group or non-production subscription first.`,
      `Apply the approved policy to representative workloads. Keep exceptions explicit, time-bound and assigned to an owner.`,
      `Roll out in controlled waves, capture the final settings and hand over the operational runbook to the named service owner.`,
    ][index],
    location: `Use the ${data.products.join(" / ")} administration experience or version-controlled IaC appropriate to the target service. Confirm the tenant, directory, subscription and environment before applying changes.`,
    decision: data.decisions[index % data.decisions.length],
    avoid: ["Do not enable enforcement before validating emergency access and recovery.", "Do not grant broad administrator roles or copy production secrets into a pilot.", "Do not create permanent exceptions to silence findings.", "Do not close the change until rollback and ownership are recorded."][index],
    outcome: ["A scoped baseline and owner-approved design are recorded.", "A pilot shows the intended policy behavior without affecting unrelated users or workloads.", "Exceptions are visible, justified and have expiry dates.", "The control is deployed in agreed scope with an owner, monitoring and a tested rollback path."][index],
  })),
  validation: data.validation.map((action, index) => ({
    action,
    expected: ["The configured value matches the approved design and applies only to the intended scope.", "A representative allowed and denied test produces the expected result; no unexpected lockout or bypass occurs."][index],
    evidence: ["Exported configuration or policy assignment, scope, owner and change reference.", "Timestamped test result, relevant audit/sign-in/resource log and reviewer name. Marking this item reviewed does not technically validate a tenant."][index],
  })),
  failures: ["Applying a broad policy before mapping legacy and service dependencies.", "Treating a portal status as proof that the end-to-end security outcome works.", "Leaving exclusions without an owner, expiry date, compensating measure or review."],
  operations: ["Name a primary and backup service owner; define change and incident escalation.", "Alert on policy drift, privileged changes, disabled telemetry and repeated exceptions.", "Review scope, service changes and exceptions at least quarterly and after material architecture changes."],
});

